import {FC, useEffect, useState} from 'react'

import '../../css/Chat.css'

import { RxAvatar } from "react-icons/rx";

interface users {
    username: string;
    password: string;
    friendList: string[];
}

interface props {
    users:users
    ChatWith: (username: string) => void
    friendAdd: string | null
}

const ChatList :FC<props> = ({users , ChatWith , friendAdd}) => {
    const [friendname,setFrinendList] = useState<string|null>(null)
    const username = localStorage.getItem('UserCampTest')
    useEffect(()=>{
        setFrinendList(friendAdd)
    },[friendAdd])

    const addFriend = async() =>{
        const fetchUser = async () => {
            const reg = await fetch(`https://camp-server-henna.vercel.app/addfriend`, {
                method: 'POST',
                mode: 'no-cors',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({username,friendname})
              });
              const data = await reg.json();
              
        }
        fetchUser()
        window.location.reload();
        setFrinendList(null)
        
    }

    const deleteFriend = async(friendname:string)=>{
        const fetchUser = async () => {
            const reg = await fetch(`https://camp-server-henna.vercel.app/deletefriend`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({username,friendname})
              });
              const data = await reg.json();
              
        }
        fetchUser()
        window.location.reload();
    }

    return (
        <div className='ChatMainContainer'>
            <h3 className='ChatH3'>Chats</h3>
            {friendname?.length == null ? 
                users.friendList?.map((names)=>(
                    <button  key={names} onClick={()=> ChatWith(names)} className='ButtonChooseChat'>
                        <div className='ChatsBlock'>
                            <RxAvatar className='AvatarChat'/>
                            <div className='InfoBlockChat'>
                                <h4 className='NamesChatListOne'>{names}</h4>
                                <p className='PChatListOne'>Last message</p>
                            </div>
                            <div className='Date'>
                                02.02.2025
                            </div>
                            <button onClick={()=>deleteFriend(names)}>Delete</button>
                        </div>
                        <div className='outline'></div>
                    </button>
                )): 
                <div className='ChatsBlock'>
                    <RxAvatar className='AvatarChat'/>
                    <div className='InfoBlockChat'>
                        <h4 className='NamesChatListOne'>{friendname}</h4>
                        <p className='PChatListOne'>Last message</p>
                    </div>
                    <div className='Date'>
                        02.02.2025
                    </div>
                    <button onClick={addFriend}>Add</button>
                </div>
            }
            
        </div>
    )
}

export default ChatList;