import { FC , useState } from 'react'
import '../css/Auth.css'

interface props {
    setIsLogin: (e: boolean)=>void
}
const Auth: FC<props> = ({setIsLogin}) => {

    const [isSwitched, setIsSwitched] = useState(false);
    const [username , setUsername] = useState('')
    const [password , setPassword] = useState('')
    const Switch = () => {
        setIsSwitched(!isSwitched)
    }
    const register = async() => {
        const res = fetch('https://camp-server-henna.vercel.app/registration',{
            method: 'POST',
            mode: 'no-cors',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({username,password})
        }).then((res) => {
            if (res.ok) {
              localStorage.setItem('AuthCampTest', "true")
              localStorage.setItem('UserCampTest', username)
              setIsLogin(true)
              return res.json(); 
            } else {
            
              throw new Error('Ошибка запроса: ' + res.statusText);
            }
          })
    }
    const login = async() => {
        const res = fetch('https://camp-server-henna.vercel.app/login',{
            method: 'POST',
            mode: 'no-cors',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({username,password})
        }).then((res) => {
            if (res.ok) {
              localStorage.setItem('AuthCampTest', "true")
              localStorage.setItem('UserCampTest', username)
              setIsLogin(true)
              return res.json(); 
            } else {
            
              throw new Error('Ошибка запроса: ' + res.statusText);
            }
          })
    }
    return (
        <div className='MainContainer'>
            {isSwitched? 
            <div className="Container">
                <h3>Register</h3>
                <button className='Switch' onClick={Switch}>Switch</button>
                <input onChange={(e)=>setUsername(e.target.value)} className="Input" placeholder="Username"></input>
                <input onChange={(e)=>setPassword(e.target.value)} className="Input" placeholder="Password"></input>
                <button onClick={register} className='ButAuth'>Register</button>
            </div>:
            <div className="Container">
                <h3>Login</h3>
                <button className='Switch' onClick={Switch}>Switch</button>
                <input onChange={(e)=>setUsername(e.target.value)} className="Input" placeholder="Username"></input>
                <input onChange={(e)=>setPassword(e.target.value)} className="Input" placeholder="Password"></input>
                <button onClick={login} className='ButAuth'>Login</button>
            </div>}
        </div>
    )
}
export default Auth;