import {FC, useEffect, useState} from 'react'
import '../css/Chat.css'

import ChatHeader from './ChatComponent/ChatHeader';
import ChatList from './ChatComponent/ChatList'

interface users {
    username: string;
    password: string;
    friendList: string[];
}
interface props {
    users:users
    ChatWith: (username: string) => void
}
const Chat : FC<props> = ({users ,ChatWith}) => {
    const [searchFr,setSearch] = useState('')
    const [friendAdd, setFriendAdd] = useState<string | null>(null)
    useEffect(()=>{
        const fetchUser = async () => {
            const reg = await fetch(`https://camp-server-henna.vercel.app/searchuser/${searchFr}`, {
                method: 'GET',
                mode: 'no-cors',
              });
              const data = await reg.json();
              console.log(data);
              setFriendAdd(data)
        }
        fetchUser()
    },[searchFr])

    return (
        <div className='ChatMainContainer'>
            <ChatHeader setSearch={setSearch}  username = {users.username}/>
            <ChatList friendAdd={friendAdd} users = {users}  ChatWith = {ChatWith}/>
        </div>
    ) 
}
export default Chat;