import { FC, useEffect, useRef, useState } from 'react';
import '../../css/DisplayChat.css';
import io from 'socket.io-client';

const socket = io('wss://https://camp-server-henna.vercel.app');

interface Props {
  Name: string;
  input:string;
  sender: number;
}

interface Message {
  sender: string;
  reciver: string
  content: string;
  timestamp: number;
}
interface ChatMessage {
  message: string;
  room: string;
  sender: string;
  reciver: string;
}

const Display: FC<Props> = ({ Name ,input ,sender}) => {
  const user1 = localStorage.getItem('UserCampTest');
  const [user2, setUser2] = useState('');
  const roomName = [user1, user2].sort().join('-');
  const [messages, setMessages] = useState<Message[]>([]);
  const [revInput,setRevInput] = useState('')
  const messagesEndRef = useRef<HTMLDivElement | null>(null);
  const messagesContainerRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    
    messagesContainerRef.current?.scrollTo({
      top: messagesContainerRef.current.scrollHeight,
      behavior: 'smooth',
    });
  }, [messages]);

  useEffect(()=>{
    setRevInput(input)
  },[input])

  useEffect(() => {
    setUser2(Name);
  }, [Name]);

  useEffect(() => {
    if (!user2) return;
  
    const fetchMessages = async () => {
      try {
        const res = await fetch(`https://camp-server-henna.vercel.app/messages?user1=${user1}&user2=${user2}`,{
          mode: 'no-cors',
        });
        const data = await res.json();
        setMessages(data);
      } catch (err) {
        console.error('Ошибка при загрузке сообщений:', err);
      }
    };
  
    fetchMessages();
  }, [user2]);
  
  useEffect(() => {
    if (!user1 || !user2) return;
    socket.emit('start-chat', { roomName });
  
    socket.on('chat message', (data: ChatMessage) => {
      const { message, room, sender ,reciver} = data;
      const newMessage: Message = {
        sender,
        reciver,
        content: message,
        timestamp: Date.now(),
      };
      setMessages((prev) => [...prev, newMessage].sort((a, b) => a.timestamp - b.timestamp));
    });
  
    return () => {
      socket.off('chat message');
    };
  }, [roomName]);
  
  useEffect(() => {
    setMessages([]); 
  }, [user2]);
  
  useEffect(()=>{
    const sendMessage = () => {
      if (revInput.trim()) {
        socket.emit('chat message', { message: revInput, room: roomName, sender: user1 , reciver: user2});
      }
    };
    sendMessage()
  },[sender])
  return (
    <div ref={messagesContainerRef} className="DisplayContainer">
      {messages.length > 0 ? (
        messages.map((msg, idx) => (
          <>
          {msg.sender === user1?
          <div className='MessageContainer' key={idx}>
             <div ref={messagesEndRef} className='sender'>{msg.sender}:{msg.content} </div> 
          </div>
          : 
          <div className='MessageContainer2' key={idx}>
            <div ref={messagesEndRef} className='reciver'>{msg.sender}:{msg.content} </div>
          </div>}
          </>
        ))
      ) : (
        <p className="DoYou">Do you want to write a message?</p>
      )}
    </div>
  );
};

export default Display;
