import { FC, useEffect, useState } from "react";

import Chat from "./Chat";
import DisplayChat from "./DisplayChat";

import '../css/Preload.css'
import Auth from "./Auth";

interface users {
    username: string;
    password: string;
    friendList: string[];
}

interface users {
    username : string;
    password : string;
    friendList : string[];
};

const Preload :FC = () => {

    const [users , setUsers] = useState<users>({
        username : 'none',
        password : '1111',
        friendList : ['Laravel' , 'Bob Joker' , 'Fieroo Botat']
    })

    const [ChatName , setChatName] = useState('Choose Chat')
    const [ChatList , setChatList] = useState([])
    const [username,setUsername] = useState('')
    const [isLogin, setIsLogin] = useState(false)

    const ChatWith = (username:string) =>{
        return setChatName(username)
    }

    useEffect(() => {
        const fetchFriend = async () => {
          try {
            if(users.username === 'none'){
                return
            }
            const res = await fetch(`https://camp-server-henna.vercel.app/getfriend/${users.username}`,{
                mode: 'no-cors',
            });
            if (!res.ok) throw new Error('Failed to fetch friends');
            const data = await res.json();
            setUsers({...users , friendList: data});
          } catch (error) {
            console.error('Error fetching friends:', error);
          }
        };
      
        fetchFriend();
      }, [users.username]);

    useEffect(()=>{
        const a = localStorage.getItem('AuthCampTest')
        setIsLogin(a === 'true');
    },[])
    
    useEffect(()=>{
        const a = localStorage.getItem('UserCampTest')
        if(a){setUsers({...users , username : a})}
    },[isLogin])

    return (
        <>
        {isLogin? 
        <div className="PreloadMainContainer">
            <Chat users = {users} ChatWith={ChatWith}/>
            <DisplayChat ChatName ={ChatName}/>
        </div>
        :
        <Auth setIsLogin ={setIsLogin}/>
        }
        </>
    )
}
export default Preload;