import {FC, use, useEffect, useState} from 'react'

import '../../css/Chat.css'

import { RxAvatar } from "react-icons/rx";
import { CiSearch } from "react-icons/ci";

interface props {
    username: string
    setSearch: (e:string)=>void
}

const ChatHeader :FC<props> = ({username ,setSearch}) => {
    const [friendname,setFrinedInput] = useState('')
    
    useEffect(()=>{
        setSearch(friendname)
    },[friendname])
    const LogOut = () => {
        localStorage.removeItem('AuthCampTest')
        localStorage.removeItem('UserCampTest')
        window.location.reload();
    }
    return (
        <div className='ChatHeader'>
            <div className='UpHeder'>
                <span className='YouName'>
                    <RxAvatar className='AvatarIcon'/>
                    <h3 className='NamesStyle'>{username}</h3>
                </span>
                <button onClick={LogOut} className='Logout'>LogOut</button>
            </div>
            <div className='DownHeder'>
                <CiSearch className='SearchIcon'/>
                <input onChange={(e)=>setFrinedInput(e.target.value)} className='Search' placeholder='Search or start new chat'></input>
            </div>
        </div>
    )
}

export default ChatHeader;