import {FC, useEffect, useState} from 'react'

import '../css/DisplayChat.css'

import DisplayHeader from './DisplayComponent/DisplayHeader';
import Display from './DisplayComponent/Display';
import DisplayWrite from './DisplayComponent/DisplayWrite';

interface props {
    ChatName:string
}
const DisplayChat : FC<props> = ({ChatName}) => {
    const [input, setInput] = useState('')
    const [Choose ,setChoose] = useState(ChatName || '')
    const [sender,setSender] = useState<number>(0)
    useEffect(()=>{
        setChoose(ChatName)
    },[ChatName])
    return (
        <div className='DisplayMainContainer'>
            <DisplayHeader Name = {Choose}/>
            <Display sender={sender} input={input} Name = {Choose}/>
            <DisplayWrite setSender={setSender} setInput={setInput}/>
        </div>
    )
}
export default DisplayChat;