import {FC, useEffect, useState} from 'react'

import '../../css/DisplayChat.css'

import { CiLocationArrow1 } from "react-icons/ci";
interface props{
    setInput: (e:string)=>void
    setSender: (e:number)=> void;
}
const DisplayWrite : FC<props> = ({setInput ,setSender}) => {
    const [message,setMessage] = useState('')
    const [send,setSend] = useState(0)
    useEffect(()=>{
        setInput(message)
    },[message])

    useEffect(()=>{
        setSender(send)
    },[send])
    
    const Send = () => {
        setSend(prev=> prev+1)
        setMessage('')
    }
    return (
        <div className='DisplayWrite'>
            <div className='OutHolderInput'>
                <input value={message} onChange={(e)=>setMessage(e.target.value)} className='InputDisplay' placeholder='Enter ypur message ...'></input>
                <button className='SendButton' onClick={Send}><CiLocationArrow1 className='IconSend'/></button>
            </div>
        </div>
    )
}
export default DisplayWrite;