import {FC, useEffect, useState} from 'react'

import '../../css/DisplayChat.css'

import { RxAvatar } from "react-icons/rx";

interface Name {
    Name: string;
}

const DisplayHeader : FC<Name> = ({Name}) => {
    const [Names , setNames] = useState<string | null>(null)
    useEffect(()=>{
        setNames(Name)
    },[Name])

    return (
        <div className='HederContainer'>
            <RxAvatar className='AvatarHeader'/>
            {Names ? <h3>{Names}</h3> : <h3>Choose Chat</h3>}
        </div>
    )
}
export default DisplayHeader;